import * as React from "react"

import { cn } from "@/lib/utils"

/**
 * Real brand marks as inline SVG, for the "I need an actual customer's logo" case (e.g. dropping the
 * Spotify or Netflix mark onto a "works with" wall). This is the deliberate counterpart to the
 * fictional {@link file://./placeholder-logos.tsx placeholder logos}: every mark here is a registered
 * trademark owned by its company. Koala UI ships the vector as a convenience only and claims no rights
 * to it, so each entry carries the brand's domain (the link to the company) and, where the brand
 * publishes one, a link to its OWN trademark / brand guidelines, which you must read and follow before
 * using the logo. The legal notice and the links are surfaced on `/docs/logos`.
 *
 * Marks are faithful single-path glyphs sourced from Simple Icons (https://simpleicons.org, CC0), so
 * they are NOT redrawn or optically rescaled the way the placeholders are: brand guidelines forbid
 * altering a logo's proportions. Color is the one knob:
 *   - by default the live mark paints in the official brand color (applied at the call site);
 *   - `mono` brands (near-black / near-white, e.g. GitHub, X, Vercel) paint in the theme foreground
 *     instead, so they stay visible on the dark and moonlight themes rather than vanishing.
 * Either way the Copy / Download export bakes the literal brand `color` in. Literal brand hex is the
 * same documented exception to the tokens-only rule as the OAuth marks in `auth-form/brand-logos.tsx`.
 *
 * Notably absent: a few household brands (Apple, LinkedIn, Slack, Adobe) whose owners disallow logo
 * redistribution and have had their marks pulled from the upstream set. That restriction is exactly
 * what the on-page notice warns about; do not hand-add them.
 *
 * To add a brand: append a `{ name, domain, color, mono?, guidelines?, path }` entry. Keep `path` a
 * faithful single-path 24x24 glyph and set `guidelines` to the brand's official usage page if it has
 * one.
 */

export interface BrandLogoEntry {
  /** Brand name, used as the card label and accessible name. */
  name: string
  /** The brand's domain: shown as the muted caption, and the brand link is `https://` + this. */
  domain: string
  /** Official brand color (literal hex: the documented brand-mark exception to tokens-only). */
  color: string
  /** Near-black/white marks: paint the live mark in the theme foreground so dark themes keep it. */
  mono?: boolean
  /** The brand's own trademark / brand-asset guidelines, when published. Read before using the mark. */
  guidelines?: string
  /** Single-path SVG geometry on a 24x24 viewBox, painting with `currentColor`. */
  path: string
}

/**
 * Real brand logos available to copy or download. Each is a trademark of its owner; where present, the
 * linked guidelines are authoritative. Ordered roughly by familiarity for a varied opening wall.
 */
