/** The brand's home page, derived from its domain. */
export function brandHref(brand: BrandLogoEntry): string {
  return `https://${brand.domain}`
}

/**
 * The generic mark shell: a 24x24 `currentColor` glyph. One renderer for every brand (the geometry is
 * data, not a bespoke component per logo). Decorative by default (`aria-hidden`); the visible brand
 * name carries the accessible label.
 */
function BrandGlyph({ path, ...props }: { path: string } & React.SVGProps<SVGSVGElement>) {
  return (
    <svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true" focusable="false" {...props}>
      <path d={path} />
    </svg>
  )
}

/**
 * Render a brand mark at a standard size. Color brands paint in their official color; `mono` brands
 * paint in the theme foreground (so they survive dark themes). The export always bakes the literal
 * brand color regardless of on-screen tone.
 */
export function BrandLogo({
  brand,
  className,
}: {
  brand: BrandLogoEntry
  className?: string
}) {
  return (
    <BrandGlyph
      path={brand.path}
      style={brand.mono ? undefined : { color: brand.color }}
      className={cn("size-9", brand.mono && "text-foreground", className)}
    />
  )
}
